/**
 * Regenerates src/data/countries.mjs.
 *
 * Run with `node scripts/generate-countries.mjs`. The generated file is
 * committed — this script exists so the list can be re-derived and reviewed as
 * a diff, not so it can be built on the fly.
 *
 * Names come from the Unicode CLDR data already inside Node, via
 * Intl.DisplayNames. No network, no dependency, no third-party service.
 *
 * CLDR knows more region codes than ISO 3166-1 assigns, so two sets are
 * removed by hand. Both are listed in full rather than pattern-matched,
 * because a country list is exactly the wrong place to be clever.
 */

// Reserved or non-country codes CLDR names but ISO 3166-1 does not assign to a
// country: supranational bodies, testing pseudo-locales, and territories that
// exist only as exceptional reservations.
const NOT_COUNTRIES = new Set([
  'AC', // Ascension Island — exceptionally reserved
  'CP', // Clipperton Island — exceptionally reserved
  'CQ', // Sark — exceptionally reserved
  'DG', // Diego Garcia — exceptionally reserved
  'EA', // Ceuta & Melilla — exceptionally reserved
  'EU', // European Union
  'EZ', // Eurozone
  'IC', // Canary Islands — exceptionally reserved
  'QO', // Outlying Oceania — CLDR grouping
  'TA', // Tristan da Cunha — exceptionally reserved
  'UN', // United Nations
  'XA', // pseudo-locale used for testing
  'XB', // pseudo-locale used for testing
  'ZZ', // unknown region
]);

// Withdrawn codes CLDR still resolves, each to the name of the country that
// replaced it. Left in, they would offer the same country twice under two
// codes — "United Kingdom" as both GB and UK — and split the reporting.
const WITHDRAWN = new Set([
  'AN', // Netherlands Antilles → Curaçao
  'BU', // Burma → Myanmar (MM)
  'CS', // Serbia and Montenegro → Serbia (RS)
  'DD', // East Germany → Germany (DE)
  'DY', // Dahomey → Benin (BJ)
  'FX', // Metropolitan France → France (FR)
  'HV', // Upper Volta → Burkina Faso (BF)
  'NH', // New Hebrides → Vanuatu (VU)
  'RH', // Southern Rhodesia → Zimbabwe (ZW)
  'SU', // Soviet Union → Russia (RU)
  'TP', // East Timor → Timor-Leste (TL)
  'UK', // not an ISO code; the United Kingdom is GB
  'VD', // North Vietnam → Vietnam (VN)
  'YD', // South Yemen → Yemen (YE)
  'YU', // Yugoslavia → Serbia (RS)
  'ZR', // Zaire → Congo - Kinshasa (CD)
]);

/* Kosovo is the one deliberate addition.
   XK is user-assigned rather than officially assigned by ISO, so it is not in
   the 249. It is what the European Commission, the IMF and most airlines use,
   and this field asks a person where they live: leaving it out would leave
   somebody with no honest answer. Counted separately so the ISO base stays
   verifiable. */
const USER_ASSIGNED = ['XK'];

const displayName = new Intl.DisplayNames(['en'], {type: 'region'});

const named = [];
for (let first = 65; first <= 90; first += 1) {
  for (let second = 65; second <= 90; second += 1) {
    const code = String.fromCharCode(first) + String.fromCharCode(second);
    let name;
    try { name = displayName.of(code); } catch { continue; }
    // An unassigned code comes back as itself.
    if (!name || name === code) continue;
    if (NOT_COUNTRIES.has(code) || WITHDRAWN.has(code)) continue;
    named.push({code, name});
  }
}

const iso = named.filter(entry => !USER_ASSIGNED.includes(entry.code));
if (iso.length !== 249) {
  throw new Error(`Expected 249 officially assigned ISO 3166-1 codes, derived ${iso.length}. `
    + 'Node\'s CLDR data has moved; review the exclusions above before committing.');
}

const countries = [...named].sort((a, b) => a.name.localeCompare(b.name, 'en'));

const file = `// Generated by scripts/generate-countries.mjs — do not edit by hand.
//
// ISO 3166-1 alpha-2 codes with CLDR English display names, sorted by name.
// ${iso.length} officially assigned codes, plus XK (Kosovo), which is
// user-assigned and included deliberately. See the generator for why each
// excluded code is excluded.
//
// The code is what a visitor submits and what is stored. The name is what they
// read. One source for both, imported by the build that renders the options
// and by the Function that validates them, so the two can never disagree.

export const COUNTRIES = Object.freeze([
${countries.map(({code, name}) => `  {code: '${code}', name: ${JSON.stringify(name)}},`).join('\n')}
]);

export const COUNTRY_CODES = Object.freeze(new Set(COUNTRIES.map(country => country.code)));

/** The display name for a stored code, or the code itself if it is unknown. */
export function countryName(code) {
  return COUNTRIES.find(country => country.code === code)?.name || code || '';
}
`;

const {writeFileSync} = await import('node:fs');
const target = new URL('../src/data/countries.mjs', import.meta.url);
writeFileSync(target, file);
console.log(`Wrote ${countries.length} countries (${iso.length} ISO + ${USER_ASSIGNED.length} user-assigned).`);
